def transform(grid):
    out = [row[:] for row in grid]
    # Fill horizontally between the outer diagonal boundary points on each row.
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v != 0]
        if len(marks) >= 2:
            for c in range(min(marks) + 1, max(marks)):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
